# owner: platform
"""Absence notices for parents, built from marks."""

from typing import Iterable, List
from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed
from datetime import date

# ---
def check_same_student(
    student: Student, marks: List[Mark]
) -> None:
    seen = {mark.student_id for mark in marks}
    others = sorted(seen - {student.student_id})
    if others:
        names = ", ".join(others)
        raise ValueError(f"foreign marks: {names}")

# ---
def absent_days(
    student: Student, marks: List[Mark]
) -> List[date]:
    check_same_student(student, marks)
    days = sorted(set(days_missed(marks)))
    if not days:
        raise ValueError("no absences to report")
    return days

# ---
def format_day(when: date) -> str:
    return f"{when:%B} {when.day}, {when.year}"

# ---
def notice_text(student: Student, days: List[date]) -> str:
    name = f"{student.first_name} {student.last_name}"
    count = len(days)
    unit = "day" if count == 1 else "days"
    listed = ", ".join(format_day(when) for when in days)
    body = f"{name} was absent on {count} {unit}: {listed}."
    closing = "Please contact the school with questions."
    return "\n\n".join(["Dear parent,", body, closing])

# ---
def absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Notice text for the days a student was absent."""
    days = absent_days(student, list(marks))
    return notice_text(student, days)
